/* Local minimal pdf-lib-compatible PDF merger for Uti-Mate. Supports many standard uncompressed PDFs. */
(function(){'use strict';function enc(s){return new TextEncoder().encode(s)}function bytesToLatin1(bytes){let s='',chunk=8192;for(let i=0;i<bytes.length;i+=chunk){let sub=bytes.subarray(i,i+chunk);s+=String.fromCharCode.apply(null,sub)}return s}function latin1ToBytes(s){const out=new Uint8Array(s.length);for(let i=0;i<s.length;i++)out[i]=s.charCodeAt(i)&255;return out}function parseObjects(str){const objs=new Map();const re=/(\d+)\s+(\d+)\s+obj\s*([\s\S]*?)\s*endobj/g;let m;while((m=re.exec(str)))objs.set(Number(m[1]),m[3]);return objs}function findPages(objs){let root=null;for(const [n,c] of objs)if(/\/Type\s*\/Catalog\b/.test(c)){root=n;break}let pages=null;if(root){const m=objs.get(root).match(/\/Pages\s+(\d+)\s+\d+\s+R/);if(m)pages=Number(m[1])}const out=[],seen=new Set();function walk(n){if(seen.has(n)||!objs.has(n))return;seen.add(n);const c=objs.get(n);if(/\/Type\s*\/Page\b/.test(c)&&!/\/Type\s*\/Pages\b/.test(c)){out.push(n);return}const kids=c.match(/\/Kids\s*\[([\s\S]*?)\]/);if(kids){let r,m;const re=/(\d+)\s+\d+\s+R/g;while((m=re.exec(kids[1])))walk(Number(m[1]));}}if(pages)walk(pages);if(!out.length){for(const [n,c] of objs)if(/\/Type\s*\/Page\b/.test(c)&&!/\/Type\s*\/Pages\b/.test(c))out.push(n)}return out}function buildPdf(objects,pageNums){const parts=[enc('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n')],offsets=[0];let pos=parts[0].length;for(let i=0;i<objects.length;i++){offsets.push(pos);const h=enc((i+1)+' 0 obj\n');parts.push(h);pos+=h.length;const b=latin1ToBytes(objects[i]);parts.push(b);pos+=b.length;const e=enc('\nendobj\n');parts.push(e);pos+=e.length}const xref=pos;let xr='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n';for(let i=1;i<offsets.length;i++)xr+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';xr+='trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';parts.push(enc(xr));let total=0;for(const p of parts)total+=p.length;const out=new Uint8Array(total);let o=0;for(const p of parts){out.set(p,o);o+=p.length}return out}class SourcePDF{constructor(bytes){this.str=bytesToLatin1(new Uint8Array(bytes));this.objects=parseObjects(this.str);this.pageRefs=findPages(this.objects)}getPageIndices(){return this.pageRefs.map((_,i)=>i)}}class MergedPDF{constructor(){this.pages=[]}async copyPages(src,indices){return indices.map(i=>({src,old:src.pageRefs[i]})).filter(p=>p.old)}addPage(p){this.pages.push(p)}async save(){if(!this.pages.length)throw new Error('No pages to merge.');const objects=['',''];let pageNewNums=[];const copiedDocs=new Map();function copyDoc(src){if(copiedDocs.has(src))return copiedDocs.get(src);const map=new Map();for(const n of src.objects.keys())map.set(n,objects.length+1+map.size);for(const [n,c] of src.objects){let out=c.replace(/(\d+)\s+\d+\s+R/g,(m,a)=>map.has(Number(a))?map.get(Number(a))+' 0 R':m);objects.push(out)}const info={map};copiedDocs.set(src,info);return info}for(const p of this.pages){const info=copyDoc(p.src);const newNum=info.map.get(p.old);pageNewNums.push(newNum)}for(const p of this.pages){const info=copiedDocs.get(p.src);const newNum=info.map.get(p.old);let idx=newNum-1;objects[idx]=objects[idx].replace(/\/Parent\s+\d+\s+\d+\s+R/,'/Parent 2 0 R')}objects[0]='<< /Type /Catalog /Pages 2 0 R >>';objects[1]='<< /Type /Pages /Count '+pageNewNums.length+' /Kids ['+pageNewNums.map(n=>n+' 0 R').join(' ')+'] >>';return buildPdf(objects,pageNewNums)}}window.PDFLib={PDFDocument:{create:async()=>new MergedPDF(),load:async bytes=>new SourcePDF(bytes)}};})();
